const CaseStudyComponent={render:(content,layout,colorMode,pStyle,lang)=>{const items=SectionUtils.lines(content);if(!items.length)return'';const t=SectionUtils.theme(colorMode,pStyle);const title=lang==='th'?'กรณีศึกษา / ผลลัพธ์':'Case Studies';const body=items.map(l=>{const [project,problem,action,result]=SectionUtils.parts(l);return `<article class="extra-card case"><h4>${project||''}</h4>${problem?`<p><b>${lang==='th'?'โจทย์':'Problem'}:</b> ${problem}</p>`:''}${action?`<p><b>${lang==='th'?'วิธีทำ':'Action'}:</b> ${action}</p>`:''}${result?`<p><b>${lang==='th'?'ผลลัพธ์':'Result'}:</b> ${result}</p>`:''}</article>`}).join('');return SectionUtils.wrap(SectionUtils.title(title,t)+`<div class="extra-grid">${body}</div>`,'case-section')}};
